"""Generic reconciliation staging; does not duplicate fiscal records or vault tables."""
from sqlalchemy import MetaData,Table,Column,String,Integer,JSON,DateTime,ForeignKey,UniqueConstraint
from .models import Company,UserAccount,Document
metadata=MetaData()
sessions=Table('reconcile_sessions',metadata,Column('id',String(36),primary_key=True),Column('owner_id',String(100),nullable=False),Column('idempotency_key',String(64),nullable=False,unique=True),Column('source',String(30),nullable=False),Column('source_sha256',String(64),nullable=False),Column('summary',JSON,nullable=False),Column('created_at',DateTime(timezone=True),nullable=False),Column('expires_at',DateTime(timezone=True),nullable=False),Column('status',String(20),nullable=False))
rows=Table('reconcile_rows',metadata,Column('session_id',ForeignKey(sessions.c.id),primary_key=True),Column('number',Integer,primary_key=True),Column('proposal',JSON,nullable=False),Column('revision',Integer,nullable=False))
decisions=Table('reconcile_decisions',metadata,Column('id',String(36),primary_key=True),Column('session_id',ForeignKey(sessions.c.id),nullable=False),Column('row_number',Integer,nullable=False),Column('actor_id',String(100),nullable=False),Column('action',String(20),nullable=False),Column('company_id',ForeignKey(Company.id)),Column('created_at',DateTime(timezone=True),nullable=False),Column('revision',Integer,nullable=False),UniqueConstraint('session_id','row_number','revision'))
aliases=Table('company_import_aliases',metadata,Column('company_id',ForeignKey(Company.id),primary_key=True),Column('normalized_name',String(220),primary_key=True),Column('original_name',String(220),nullable=False),Column('session_id',String(36),nullable=False),Column('actor_id',String(100),nullable=False),Column('created_at',DateTime(timezone=True),nullable=False))
permissions=Table('company_import_permissions',metadata,Column('user_id',ForeignKey(UserAccount.id),primary_key=True),Column('company_id',ForeignKey(Company.id),primary_key=True))
history=Table('reconcile_history',metadata,Column('id',String(36),primary_key=True),Column('session_id',String(36)),Column('actor_id',String(100),nullable=False),Column('action',String(30),nullable=False),Column('created_at',DateTime(timezone=True),nullable=False),Column('counts',JSON,nullable=False))
